/* Typed transformations for Accounts, Activities, Campaigns, Contacts, Date, Leads, OpportunityProducts and Products.
   Rebuilds these eight Silver tables from all Bronze rows. Bronze is immutable. Duplicate business keys are quarantined as a group.
   OpportunityProducts deliberately has no uniqueness constraint on (OpportunityID, ProductID): repeated pairs may be valid lines. */
CREATE OR ALTER PROCEDURE slv.usp_TransformRemainingEntities
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRAN;
 DELETE FROM ctl.DataQualityException WHERE EntityName IN ('Accounts','Activities','Campaigns','Contacts','Date','Leads','OpportunityProducts','Products');
 DELETE FROM slv.Accounts; DELETE FROM slv.Activities; DELETE FROM slv.Campaigns; DELETE FROM slv.Contacts;
 DELETE FROM slv.CalendarDate; DELETE FROM slv.Leads; DELETE FROM slv.OpportunityProducts; DELETE FROM slv.Products;

 /* Accounts: unique AccountID; invalid typed numeric values quarantined. */
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(AccountID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(AccountID)),'')) n FROM brz.Accounts b)
 INSERT ctl.DataQualityException(RuleCode,EntityName,BusinessKey,BronzeRowID,IngestionBatchID,Severity,Details)
 SELECT CASE WHEN k IS NULL THEN 'ACCOUNT_MISSING_KEY' WHEN n>1 THEN 'ACCOUNT_DUPLICATE_KEY' ELSE 'ACCOUNT_INVALID_VALUE' END,'Accounts',k,BronzeRowID,IngestionBatchID,'ERROR','Account excluded: missing/duplicate key or invalid numeric field.'
 FROM x WHERE k IS NULL OR n>1 OR (NULLIF(LTRIM(RTRIM(AnnualRevenue)),'') IS NOT NULL AND (TRY_CONVERT(decimal(19,4),AnnualRevenue) IS NULL OR TRY_CONVERT(decimal(19,4),AnnualRevenue)<0))
 OR (NULLIF(LTRIM(RTRIM(Employees)),'') IS NOT NULL AND (TRY_CONVERT(int,Employees) IS NULL OR TRY_CONVERT(int,Employees)<0));
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(AccountID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(AccountID)),'')) n FROM brz.Accounts b)
 INSERT slv.Accounts(AccountID,AccountName,Industry,Country,City,Segment,TerritoryID,AnnualRevenueAED,Employees,AccountStatus,SourceBronzeRowID,IngestionBatchID)
 SELECT k,NULLIF(LTRIM(RTRIM(AccountName)),''),NULLIF(LTRIM(RTRIM(Industry)),''),NULLIF(LTRIM(RTRIM(Country)),''),NULLIF(LTRIM(RTRIM(City)),''),NULLIF(LTRIM(RTRIM(Segment)),''),NULLIF(LTRIM(RTRIM(TerritoryID)),''),TRY_CONVERT(decimal(19,4),NULLIF(LTRIM(RTRIM(AnnualRevenue)),'')),TRY_CONVERT(int,NULLIF(LTRIM(RTRIM(Employees)),'')),CASE UPPER(LTRIM(RTRIM(AccountStatus))) WHEN 'ACTIVE' THEN 'Active' WHEN 'INACTIVE' THEN 'Inactive' ELSE NULLIF(LTRIM(RTRIM(AccountStatus)),'') END,BronzeRowID,IngestionBatchID
 FROM x WHERE k IS NOT NULL AND n=1 AND (NULLIF(LTRIM(RTRIM(AnnualRevenue)),'') IS NULL OR TRY_CONVERT(decimal(19,4),AnnualRevenue)>=0) AND (NULLIF(LTRIM(RTRIM(Employees)),'') IS NULL OR TRY_CONVERT(int,Employees)>=0);

 /* Activities */
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(ActivityID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(ActivityID)),'')) n FROM brz.Activities b)
 INSERT ctl.DataQualityException(RuleCode,EntityName,BusinessKey,BronzeRowID,IngestionBatchID,Severity,Details)
 SELECT CASE WHEN k IS NULL THEN 'ACTIVITY_MISSING_KEY' WHEN n>1 THEN 'ACTIVITY_DUPLICATE_KEY' ELSE 'ACTIVITY_INVALID_VALUE' END,'Activities',k,BronzeRowID,IngestionBatchID,'ERROR','Activity excluded: missing/duplicate ID, invalid date or invalid duration.'
 FROM x WHERE k IS NULL OR n>1 OR (NULLIF(LTRIM(RTRIM(ActivityDate)),'') IS NOT NULL AND TRY_CONVERT(date,ActivityDate) IS NULL) OR (NULLIF(LTRIM(RTRIM(DurationMinutes)),'') IS NOT NULL AND (TRY_CONVERT(int,DurationMinutes) IS NULL OR TRY_CONVERT(int,DurationMinutes)<0));
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(ActivityID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(ActivityID)),'')) n FROM brz.Activities b)
 INSERT slv.Activities(ActivityID,OpportunityID,AccountID,SalesRepID,ActivityDate,ActivityType,Outcome,DurationMinutes,SourceBronzeRowID,IngestionBatchID)
 SELECT k,NULLIF(LTRIM(RTRIM(OpportunityID)),''),NULLIF(LTRIM(RTRIM(AccountID)),''),NULLIF(LTRIM(RTRIM(SalesRepID)),''),TRY_CONVERT(date,NULLIF(LTRIM(RTRIM(ActivityDate)),'')),NULLIF(LTRIM(RTRIM(ActivityType)),''),NULLIF(LTRIM(RTRIM(Outcome)),''),TRY_CONVERT(int,NULLIF(LTRIM(RTRIM(DurationMinutes)),'')),BronzeRowID,IngestionBatchID FROM x WHERE k IS NOT NULL AND n=1 AND (NULLIF(LTRIM(RTRIM(ActivityDate)),'') IS NULL OR TRY_CONVERT(date,ActivityDate) IS NOT NULL) AND (NULLIF(LTRIM(RTRIM(DurationMinutes)),'') IS NULL OR TRY_CONVERT(int,DurationMinutes)>=0);

 /* Campaigns */
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(CampaignID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(CampaignID)),'')) n FROM brz.Campaigns b)
 INSERT ctl.DataQualityException(RuleCode,EntityName,BusinessKey,BronzeRowID,IngestionBatchID,Severity,Details)
 SELECT CASE WHEN k IS NULL THEN 'CAMPAIGN_MISSING_KEY' WHEN n>1 THEN 'CAMPAIGN_DUPLICATE_KEY' ELSE 'CAMPAIGN_INVALID_VALUE' END,'Campaigns',k,BronzeRowID,IngestionBatchID,'ERROR','Campaign excluded: missing/duplicate ID, invalid date or invalid budget.' FROM x WHERE k IS NULL OR n>1 OR (NULLIF(LTRIM(RTRIM(StartDate)),'') IS NOT NULL AND TRY_CONVERT(date,StartDate) IS NULL) OR (NULLIF(LTRIM(RTRIM(Budget)),'') IS NOT NULL AND (TRY_CONVERT(decimal(19,4),Budget) IS NULL OR TRY_CONVERT(decimal(19,4),Budget)<0));
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(CampaignID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(CampaignID)),'')) n FROM brz.Campaigns b)
 INSERT slv.Campaigns(CampaignID,CampaignName,CampaignType,StartDate,BudgetAED,TargetSegment,SourceBronzeRowID,IngestionBatchID)
 SELECT k,NULLIF(LTRIM(RTRIM(CampaignName)),''),NULLIF(LTRIM(RTRIM(CampaignType)),''),TRY_CONVERT(date,NULLIF(LTRIM(RTRIM(StartDate)),'')),TRY_CONVERT(decimal(19,4),NULLIF(LTRIM(RTRIM(Budget)),'')),NULLIF(LTRIM(RTRIM(TargetSegment)),''),BronzeRowID,IngestionBatchID FROM x WHERE k IS NOT NULL AND n=1 AND (NULLIF(LTRIM(RTRIM(StartDate)),'') IS NULL OR TRY_CONVERT(date,StartDate) IS NOT NULL) AND (NULLIF(LTRIM(RTRIM(Budget)),'') IS NULL OR TRY_CONVERT(decimal(19,4),Budget)>=0);

 /* Contacts */
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(ContactID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(ContactID)),'')) n FROM brz.Contacts b)
 INSERT ctl.DataQualityException(RuleCode,EntityName,BusinessKey,BronzeRowID,IngestionBatchID,Severity,Details)
 SELECT CASE WHEN k IS NULL THEN 'CONTACT_MISSING_KEY' WHEN n>1 THEN 'CONTACT_DUPLICATE_KEY' ELSE 'CONTACT_INVALID_BOOLEAN' END,'Contacts',k,BronzeRowID,IngestionBatchID,'ERROR','Contact excluded: missing/duplicate ID or EmailOptIn is not a recognized boolean.' FROM x WHERE k IS NULL OR n>1 OR (NULLIF(LTRIM(RTRIM(EmailOptIn)),'') IS NOT NULL AND UPPER(LTRIM(RTRIM(EmailOptIn))) NOT IN ('1','0','TRUE','FALSE','YES','NO','Y','N'));
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(ContactID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(ContactID)),'')) n FROM brz.Contacts b)
 INSERT slv.Contacts(ContactID,AccountID,ContactName,JobTitle,EmailOptIn,SourceBronzeRowID,IngestionBatchID)
 SELECT k,NULLIF(LTRIM(RTRIM(AccountID)),''),NULLIF(LTRIM(RTRIM(ContactName)),''),NULLIF(LTRIM(RTRIM(JobTitle)),''),CASE WHEN UPPER(LTRIM(RTRIM(EmailOptIn))) IN ('1','TRUE','YES','Y') THEN 1 WHEN UPPER(LTRIM(RTRIM(EmailOptIn))) IN ('0','FALSE','NO','N') THEN 0 ELSE NULL END,BronzeRowID,IngestionBatchID FROM x WHERE k IS NOT NULL AND n=1 AND (NULLIF(LTRIM(RTRIM(EmailOptIn)),'') IS NULL OR UPPER(LTRIM(RTRIM(EmailOptIn))) IN ('1','0','TRUE','FALSE','YES','NO','Y','N'));

 /* Date: source date is authoritative; verify other attributes agree with it. */
 ;WITH x AS(SELECT b.*,TRY_CONVERT(date,[Date]) d,COUNT(*) OVER(PARTITION BY TRY_CONVERT(date,[Date])) n FROM brz.[Date] b)
 INSERT ctl.DataQualityException(RuleCode,EntityName,BusinessKey,BronzeRowID,IngestionBatchID,Severity,Details)
 SELECT CASE WHEN d IS NULL THEN 'DATE_INVALID_KEY' WHEN n>1 THEN 'DATE_DUPLICATE_KEY' ELSE 'DATE_ATTRIBUTE_MISMATCH' END,'Date',CONVERT(nvarchar(30),d,23),BronzeRowID,IngestionBatchID,'ERROR','Date row excluded: invalid/duplicate date or calendar attributes disagree with the date.' FROM x WHERE d IS NULL OR n>1 OR (NULLIF(LTRIM(RTRIM([Year])),'') IS NOT NULL AND (TRY_CONVERT(int,[Year]) IS NULL OR TRY_CONVERT(int,[Year])<>YEAR(d))) OR (NULLIF(LTRIM(RTRIM(MonthNumber)),'') IS NOT NULL AND (TRY_CONVERT(int,MonthNumber) IS NULL OR TRY_CONVERT(int,MonthNumber)<>MONTH(d))) OR (NULLIF(LTRIM(RTRIM(YearMonth)),'') IS NOT NULL AND LTRIM(RTRIM(YearMonth))<>CONVERT(char(7),d,126)) OR (NULLIF(LTRIM(RTRIM([Month])),'') IS NOT NULL AND UPPER(LTRIM(RTRIM([Month])))<>UPPER(LEFT(DATENAME(month,d),3))) OR (NULLIF(LTRIM(RTRIM([Quarter])),'') IS NOT NULL AND UPPER(LTRIM(RTRIM([Quarter])))<>CONCAT('Q',DATEPART(quarter,d))) OR (NULLIF(LTRIM(RTRIM(WeekNumber)),'') IS NOT NULL AND (TRY_CONVERT(int,WeekNumber) IS NULL OR TRY_CONVERT(int,WeekNumber) NOT BETWEEN 1 AND 53)) OR (NULLIF(LTRIM(RTRIM(IsMonthEnd)),'') IS NOT NULL AND (UPPER(LTRIM(RTRIM(IsMonthEnd))) NOT IN ('1','0','TRUE','FALSE','YES','NO','Y','N') OR (UPPER(LTRIM(RTRIM(IsMonthEnd))) IN ('1','TRUE','YES','Y') AND d<>EOMONTH(d)) OR (UPPER(LTRIM(RTRIM(IsMonthEnd))) IN ('0','FALSE','NO','N') AND d=EOMONTH(d))));
 ;WITH x AS(SELECT b.*,TRY_CONVERT(date,[Date]) d,COUNT(*) OVER(PARTITION BY TRY_CONVERT(date,[Date])) n FROM brz.[Date] b)
 INSERT slv.CalendarDate(SilverDateKey,CalendarDate,CalendarYear,MonthNumber,MonthName,YearMonth,CalendarQuarter,WeekNumber,IsMonthEnd,SourceBronzeRowID,IngestionBatchID)
 SELECT CONVERT(int,CONVERT(char(8),d,112)),d,YEAR(d),MONTH(d),DATENAME(month,d),CONVERT(char(7),d,126),CONCAT('Q',DATEPART(quarter,d)),TRY_CONVERT(tinyint,WeekNumber),CASE WHEN UPPER(LTRIM(RTRIM(IsMonthEnd))) IN ('1','TRUE','YES','Y') THEN 1 WHEN UPPER(LTRIM(RTRIM(IsMonthEnd))) IN ('0','FALSE','NO','N') THEN 0 ELSE NULL END,BronzeRowID,IngestionBatchID
 FROM x WHERE d IS NOT NULL AND n=1 AND (NULLIF(LTRIM(RTRIM([Year])),'') IS NULL OR TRY_CONVERT(int,[Year])=YEAR(d)) AND (NULLIF(LTRIM(RTRIM(MonthNumber)),'') IS NULL OR TRY_CONVERT(int,MonthNumber)=MONTH(d)) AND (NULLIF(LTRIM(RTRIM(YearMonth)),'') IS NULL OR LTRIM(RTRIM(YearMonth))=CONVERT(char(7),d,126)) AND (NULLIF(LTRIM(RTRIM([Month])),'') IS NULL OR UPPER(LTRIM(RTRIM([Month])))=UPPER(LEFT(DATENAME(month,d),3))) AND (NULLIF(LTRIM(RTRIM([Quarter])),'') IS NULL OR UPPER(LTRIM(RTRIM([Quarter])) )=CONCAT('Q',DATEPART(quarter,d))) AND (NULLIF(LTRIM(RTRIM(WeekNumber)),'') IS NULL OR TRY_CONVERT(tinyint,WeekNumber) BETWEEN 1 AND 53) AND (NULLIF(LTRIM(RTRIM(IsMonthEnd)),'') IS NULL OR (UPPER(LTRIM(RTRIM(IsMonthEnd))) IN ('1','TRUE','YES','Y') AND d=EOMONTH(d)) OR (UPPER(LTRIM(RTRIM(IsMonthEnd))) IN ('0','FALSE','NO','N') AND d<>EOMONTH(d)));

 /* Leads */
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(LeadID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(LeadID)),'')) n FROM brz.Leads b)
 INSERT ctl.DataQualityException(RuleCode,EntityName,BusinessKey,BronzeRowID,IngestionBatchID,Severity,Details)
 SELECT CASE WHEN k IS NULL THEN 'LEAD_MISSING_KEY' WHEN n>1 THEN 'LEAD_DUPLICATE_KEY' ELSE 'LEAD_INVALID_VALUE' END,'Leads',k,BronzeRowID,IngestionBatchID,'ERROR','Lead excluded: missing/duplicate key, invalid date/score/status, or converted-date rule violation.' FROM x WHERE k IS NULL OR n>1 OR (NULLIF(LTRIM(RTRIM(CreatedDate)),'') IS NOT NULL AND TRY_CONVERT(date,CreatedDate) IS NULL) OR (NULLIF(LTRIM(RTRIM(ConvertedDate)),'') IS NOT NULL AND TRY_CONVERT(date,ConvertedDate) IS NULL) OR (NULLIF(LTRIM(RTRIM(LeadScore)),'') IS NOT NULL AND (TRY_CONVERT(decimal(9,4),LeadScore) IS NULL OR TRY_CONVERT(decimal(9,4),LeadScore) NOT BETWEEN 0 AND 100)) OR UPPER(LTRIM(RTRIM(Status))) NOT IN ('OPEN','CONVERTED','NURTURE','DISQUALIFIED') OR (UPPER(LTRIM(RTRIM(Status)))='CONVERTED' AND TRY_CONVERT(date,ConvertedDate) IS NULL) OR (UPPER(LTRIM(RTRIM(Status)))<>'CONVERTED' AND NULLIF(LTRIM(RTRIM(ConvertedDate)),'') IS NOT NULL);
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(LeadID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(LeadID)),'')) n FROM brz.Leads b)
 INSERT slv.Leads(LeadID,CreatedDate,AccountID,LeadSource,Industry,LeadScore,LeadStatus,ConvertedDate,SalesRepID,SourceBronzeRowID,IngestionBatchID)
 SELECT k,TRY_CONVERT(date,NULLIF(LTRIM(RTRIM(CreatedDate)),'')),NULLIF(LTRIM(RTRIM(AccountID)),''),NULLIF(LTRIM(RTRIM(LeadSource)),''),NULLIF(LTRIM(RTRIM(Industry)),''),TRY_CONVERT(decimal(9,4),NULLIF(LTRIM(RTRIM(LeadScore)),'')),CASE UPPER(LTRIM(RTRIM(Status))) WHEN 'OPEN' THEN 'Open' WHEN 'CONVERTED' THEN 'Converted' WHEN 'NURTURE' THEN 'Nurture' WHEN 'DISQUALIFIED' THEN 'Disqualified' END,TRY_CONVERT(date,NULLIF(LTRIM(RTRIM(ConvertedDate)),'')),NULLIF(LTRIM(RTRIM(SalesRepID)),''),BronzeRowID,IngestionBatchID
 FROM x WHERE k IS NOT NULL AND n=1 AND (NULLIF(LTRIM(RTRIM(CreatedDate)),'') IS NULL OR TRY_CONVERT(date,CreatedDate) IS NOT NULL) AND (NULLIF(LTRIM(RTRIM(ConvertedDate)),'') IS NULL OR TRY_CONVERT(date,ConvertedDate) IS NOT NULL) AND (NULLIF(LTRIM(RTRIM(LeadScore)),'') IS NULL OR TRY_CONVERT(decimal(9,4),LeadScore) BETWEEN 0 AND 100) AND UPPER(LTRIM(RTRIM(Status)) ) IN ('OPEN','CONVERTED','NURTURE','DISQUALIFIED') AND ((UPPER(LTRIM(RTRIM(Status)))='CONVERTED' AND TRY_CONVERT(date,ConvertedDate) IS NOT NULL) OR (UPPER(LTRIM(RTRIM(Status)))<>'CONVERTED' AND NULLIF(LTRIM(RTRIM(ConvertedDate)),'') IS NULL));

 /* OpportunityProducts: each physical source row becomes one Silver line; repeated opportunity/product pairs are retained. */
 INSERT ctl.DataQualityException(RuleCode,EntityName,BusinessKey,BronzeRowID,IngestionBatchID,Severity,Details)
 SELECT 'OPP_PRODUCT_INVALID_VALUE','OpportunityProducts',CONCAT(NULLIF(LTRIM(RTRIM(OpportunityID)),''),'|',NULLIF(LTRIM(RTRIM(ProductID)),'')),BronzeRowID,IngestionBatchID,'ERROR','Product line excluded due to missing identifiers or invalid quantity/discount/revenue/cost.'
 FROM brz.OpportunityProducts WHERE NULLIF(LTRIM(RTRIM(OpportunityID)),'') IS NULL OR NULLIF(LTRIM(RTRIM(ProductID)),'') IS NULL OR (NULLIF(LTRIM(RTRIM(Quantity)),'') IS NOT NULL AND (TRY_CONVERT(decimal(19,4),Quantity) IS NULL OR TRY_CONVERT(decimal(19,4),Quantity)<0)) OR (NULLIF(LTRIM(RTRIM(DiscountPct)),'') IS NOT NULL AND (TRY_CONVERT(decimal(9,4),DiscountPct) IS NULL OR TRY_CONVERT(decimal(9,4),DiscountPct) NOT BETWEEN 0 AND 100)) OR (NULLIF(LTRIM(RTRIM(LineRevenue)),'') IS NOT NULL AND (TRY_CONVERT(decimal(19,4),LineRevenue) IS NULL OR TRY_CONVERT(decimal(19,4),LineRevenue)<0)) OR (NULLIF(LTRIM(RTRIM(EstimatedCost)),'') IS NOT NULL AND (TRY_CONVERT(decimal(19,4),EstimatedCost) IS NULL OR TRY_CONVERT(decimal(19,4),EstimatedCost)<0));
 INSERT slv.OpportunityProducts(OpportunityID,ProductID,Quantity,DiscountPct,LineRevenueAED,EstimatedCostAED,SourceBronzeRowID,IngestionBatchID)
 SELECT LTRIM(RTRIM(OpportunityID)),LTRIM(RTRIM(ProductID)),TRY_CONVERT(decimal(19,4),NULLIF(LTRIM(RTRIM(Quantity)),'')),TRY_CONVERT(decimal(9,4),NULLIF(LTRIM(RTRIM(DiscountPct)),'')),TRY_CONVERT(decimal(19,4),NULLIF(LTRIM(RTRIM(LineRevenue)),'')),TRY_CONVERT(decimal(19,4),NULLIF(LTRIM(RTRIM(EstimatedCost)),'')),BronzeRowID,IngestionBatchID
 FROM brz.OpportunityProducts WHERE NULLIF(LTRIM(RTRIM(OpportunityID)),'') IS NOT NULL AND NULLIF(LTRIM(RTRIM(ProductID)),'') IS NOT NULL AND (NULLIF(LTRIM(RTRIM(Quantity)),'') IS NULL OR TRY_CONVERT(decimal(19,4),Quantity)>=0) AND (NULLIF(LTRIM(RTRIM(DiscountPct)),'') IS NULL OR TRY_CONVERT(decimal(9,4),DiscountPct) BETWEEN 0 AND 100) AND (NULLIF(LTRIM(RTRIM(LineRevenue)),'') IS NULL OR TRY_CONVERT(decimal(19,4),LineRevenue)>=0) AND (NULLIF(LTRIM(RTRIM(EstimatedCost)),'') IS NULL OR TRY_CONVERT(decimal(19,4),EstimatedCost)>=0);

 /* Products */
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(ProductID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(ProductID)),'')) n FROM brz.Products b)
 INSERT ctl.DataQualityException(RuleCode,EntityName,BusinessKey,BronzeRowID,IngestionBatchID,Severity,Details)
 SELECT CASE WHEN k IS NULL THEN 'PRODUCT_MISSING_KEY' WHEN n>1 THEN 'PRODUCT_DUPLICATE_KEY' ELSE 'PRODUCT_INVALID_VALUE' END,'Products',k,BronzeRowID,IngestionBatchID,'ERROR','Product excluded: missing/duplicate ID, invalid unit price, margin or active flag.' FROM x WHERE k IS NULL OR n>1 OR (NULLIF(LTRIM(RTRIM(UnitPrice)),'') IS NOT NULL AND (TRY_CONVERT(decimal(19,4),UnitPrice) IS NULL OR TRY_CONVERT(decimal(19,4),UnitPrice)<0)) OR (NULLIF(LTRIM(RTRIM(StandardMarginPct)),'') IS NOT NULL AND (TRY_CONVERT(decimal(9,4),StandardMarginPct) IS NULL OR TRY_CONVERT(decimal(9,4),StandardMarginPct) NOT BETWEEN 0 AND 100)) OR (NULLIF(LTRIM(RTRIM(Active)),'') IS NOT NULL AND UPPER(LTRIM(RTRIM(Active))) NOT IN ('1','0','TRUE','FALSE','YES','NO','Y','N'));
 ;WITH x AS(SELECT b.*,NULLIF(LTRIM(RTRIM(ProductID)),'') k,COUNT(*) OVER(PARTITION BY NULLIF(LTRIM(RTRIM(ProductID)),'')) n FROM brz.Products b)
 INSERT slv.Products(ProductID,ProductName,Category,UnitPriceAED,StandardMarginPct,IsActive,SourceBronzeRowID,IngestionBatchID)
 SELECT k,NULLIF(LTRIM(RTRIM(ProductName)),''),NULLIF(LTRIM(RTRIM(Category)),''),TRY_CONVERT(decimal(19,4),NULLIF(LTRIM(RTRIM(UnitPrice)),'')),TRY_CONVERT(decimal(9,4),NULLIF(LTRIM(RTRIM(StandardMarginPct)),'')),CASE WHEN UPPER(LTRIM(RTRIM(Active))) IN ('1','TRUE','YES','Y') THEN 1 WHEN UPPER(LTRIM(RTRIM(Active))) IN ('0','FALSE','NO','N') THEN 0 ELSE NULL END,BronzeRowID,IngestionBatchID
 FROM x WHERE k IS NOT NULL AND n=1 AND (NULLIF(LTRIM(RTRIM(UnitPrice)),'') IS NULL OR TRY_CONVERT(decimal(19,4),UnitPrice)>=0) AND (NULLIF(LTRIM(RTRIM(StandardMarginPct)),'') IS NULL OR TRY_CONVERT(decimal(9,4),StandardMarginPct) BETWEEN 0 AND 100) AND (NULLIF(LTRIM(RTRIM(Active)),'') IS NULL OR UPPER(LTRIM(RTRIM(Active))) IN ('1','0','TRUE','FALSE','YES','NO','Y','N'));
 COMMIT;
END;
GO
